#include "wled.h"

#if defined(CASTLETEK_WLED_COMPAT) && defined(ARDUINO_ARCH_ESP32)
#include <esp_netif.h>

// AI: below section was generated by an AI
// Prepare the AP netif before softAPConfig enables it and starts DHCP. A setup
// accessory serves its local subnet; it must not claim the phone's Internet route.
// Arduino 2/IDF 4 creates both netifs when STA starts, even before AP is enabled.
// https://developer.apple.com/forums/thread/734344
bool castleTekWLEDPrepareLocalAP() {
  if (WiFi.getMode() == WIFI_MODE_NULL && !WiFi.mode(WIFI_STA)) return false;
  esp_netif_t* netif = esp_netif_get_handle_from_ifkey("WIFI_AP_DEF");
  if (!netif) return false;

  const esp_err_t stopped = esp_netif_dhcps_stop(netif);
  if (stopped != ESP_OK && stopped != ESP_ERR_ESP_NETIF_DHCP_ALREADY_STOPPED) return false;

  // IDF's option 32 controls DHCP Router (option 3), not the AP interface IP.
  // Use its byte-sized offer value while DHCP is stopped; softAPConfig restarts it.
  // IDF 4 always emits DNS option 6, even with OFFER_DNS disabled. Do not claim
  // otherwise or alter station DNS to work around it; wildcard DNS is absent.
  uint8_t offerRouter = 0;
  return esp_netif_dhcps_option(netif, ESP_NETIF_OP_SET,
                               ESP_NETIF_ROUTER_SOLICITATION_ADDRESS,
                               &offerRouter, sizeof(offerRouter)) == ESP_OK;
}
// AI: end
#endif
